 heat: '<path d="M12 3c3 5-2 5 2 9 1-2 2-2 2-4 5 5 6 12-3 13C4 22 2 14 7 9c-1 7 7 6 5-6Z"/>',
 screen: '<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8m-4-4v4"/>',
